// URL Routing Helper
const getUrlPath = () => window.location.pathname;

const App: React.FC = () => {
  const [currentPath, setCurrentPath] = useState(getUrlPath());

  // --- GLOBAL STATE ---
  const [currentUser, setCurrentUser] = useState<Employee | null>(null);

  // Data State
  const [orders, setOrders] = useState<DetailedOrder[]>(MOCK_DETAILED_ORDERS);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_TRANSACTIONS);
  const [customers, setCustomers] = useState<Customer[]>(MOCK_CUSTOMERS);
  const [employeesState, setEmployeesState] = useState<Employee[]>(MOCK_EMPLOYEES);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY_ITEMS);
  const [categories, setCategories] = useState<Category[]>(MOCK_CATEGORIES);
  const [discounts, setDiscounts] = useState<DiscountCode[]>(MOCK_DISCOUNTS);

  // Advanced Module State
  const [floorPlanTables, setFloorPlanTables] = useState<DiningTable[]>(MOCK_FLOOR_TABLES);
  const [kdsSettings, setKdsSettings] = useState<KDSSettings>(MOCK_KDS_SETTINGS);
  const [integrationConfig, setIntegrationConfig] = useState<AppIntegrationConfig>({
      reservation_pos: true,
      scheduling_pos: false,
      scheduling_reservation: false,
      kdsEnabled: MOCK_KDS_SETTINGS.isEnabled, // Sync with KDS settings' global enable flag
  });
  const [receiptSettings, setReceiptSettings] = useState(MOCK_RECEIPT_SETTINGS);

  // Navigation State
  const [activeTab, setActiveTab] = useState('Home');
  const [expandedMenu, setExpandedMenu] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // --- EFFECTS ---
  useEffect(() => {
    const handlePopState = () => setCurrentPath(window.location.pathname);
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  // Update KDS enabled state in integrationConfig when kdsSettings changes
  useEffect(() => {
    setIntegrationConfig(prev => ({...prev, kdsEnabled: kdsSettings.isEnabled}));
  }, [kdsSettings.isEnabled]);

  // --- ACTIONS ---
  const handleLogin = (user: Employee) => {
    setCurrentUser(user);
    if (user.role === UserRole.CASHIER) {
      setActiveTab('New Sale'); // Direct Cashier to POS App Launcher
    } else if (user.role === UserRole.SUPER_ADMIN) {
      setActiveTab('SuperAdmin');
    } else {
      setActiveTab('Home');
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveTab('Login');
  };

  const handleProcessSale = (cart: any[], total: number) => {
    const newOrder: DetailedOrder = {
      id: `ORD-${Date.now()}`,
      date: new Date().toLocaleDateString(),
      time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
      total: total,
      status: 'Paid',
      paymentMethod: 'Card', // Defaulting to Card since CashierPOS handles payments internally but triggers this for recording
      employeeName: currentUser?.name || 'Staff',
      device: 'Main Register',
      type: 'Dine-in', // Default
      items: cart
    };

    setOrders([newOrder, ...orders]);
    setTransactions([{
      id: `TRX-${Date.now()}`,
      date: new Date().toLocaleDateString(),
      amount: total,
      type: 'Sale',
      method: 'Card', 
      employeeId: currentUser?.id || 'E001'
    }, ...transactions]);
  };

  const handleAddEmployee = (emp: Employee) => {
    setEmployeesState([...employeesState, emp]);
    console.log("Synced new employee to Scheduling:", emp.name);
  };

  const handleUpdateEmployee = (updatedEmp: Employee) => {
    setEmployeesState(prev => prev.map(emp => emp.id === updatedEmp.id ? updatedEmp : emp));
    console.log("Updated employee info:", updatedEmp.name);
  };

  const handleDeleteEmployee = (id: string) => {
    if (window.confirm("Are you sure you want to delete this employee?")) {
        setEmployeesState(prev => prev.filter(emp => emp.id !== id));
    }
  };

  const handleSaveFloorPlan = (tables: DiningTable[]) => {
    setFloorPlanTables(tables);
    console.log("Floor plan saved globally:", tables.length, "items");
  };

  const handleFireToKitchen = (kitchenPayload: any) => {
    // In a real app, this would send to a backend KDS service
    console.log("Order Fired to Kitchen:", kitchenPayload);
  };


  // --- NAVIGATION CONFIG ---
  const menuItems = [
    { id: 'New Sale', label: 'New Sale', icon: <ShoppingCart size={20} />, action: () => setActiveTab('New Sale') },
    { id: 'Home', label: 'Home', icon: <LayoutDashboard size={20} />, action: () => setActiveTab('Home') },
    { 
      id: 'Sales Activity', label: 'Sales Activity', icon: <Activity size={20} />, 
      subItems: ['Orders', 'Transactions', 'Cash Log', 'Invoices', 'Recurring Payments'] 
    },
    { 
      id: 'Reports', label: 'Reports', icon: <FileBarChart size={20} />, 
      subItems: ['Sales Report', 'Employee Sales', 'Peer Insights', 'Item Sales', 'Removed Items', 'Tender Types', 'Discounts Report', 'Gift Cards Report', 'Requested Reports'] 
    },
    { 
      id: 'Finances', label: 'Finances', icon: <DollarSign size={20} />, 
      subItems: ['Overview', 'Closeout', 'Deposits', 'Statements', 'Taxes', 'Disputes', 'Pay Bills'] 
    },
    { 
      id: 'Items', label: 'Items', icon: <Package size={20} />, 
      subItems: ['Item Library', 'Categories', 'Modifier Groups', 'Printer Labels', 'Discounts'] 
    },
    { 
      id: 'Employees', label: 'Employees', icon: <Users size={20} />, 
      subItems: ['Employee List', 'Schedule', 'Time Clock'] 
    },
    { 
      id: 'Customers', label: 'Customers', icon: <User size={20} />, 
      subItems: ['Customer List', 'Feedback'] 
    },
    { 
      id: 'More', label: 'More', icon: <MoreHorizontal size={20} />, 
      subItems: ['Byte Dining', 'App Market'] 
    },
  ];

  // --- RENDER HELPERS ---
  const toggleSubMenu = (id: string) => {
    setExpandedMenu(expandedMenu === id ? null : id);
  };

  const renderSidebar = () => (
    <aside className={`bg-slate-900 text-slate-300 flex flex-col transition-all duration-300 ${isSidebarOpen ? 'w-64' : 'w-20'} shrink-0 h-screen overflow-hidden`}>
      <div className="p-4 border-b border-slate-800 flex items-center justify-between">
        {isSidebarOpen && <span className="font-bold text-white text-lg tracking-tight">OmniCommand</span>}
        <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white">
          <Menu size={20} />
        </button>
      </div>

      <nav className="flex-1 overflow-y-auto py-4 space-y-1">
        {menuItems.map((item) => (
          <div key={item.id}>
            {item.subItems ? (
              <>
                <button
                  onClick={() => isSidebarOpen ? toggleSubMenu(item.id) : setActiveTab(item.subItems[0])}
                  className={`w-full flex items-center justify-between px-4 py-3 hover:bg-slate-800 hover:text-white transition-colors
                    ${activeTab === item.id || (item.subItems && item.subItems.includes(activeTab)) ? 'text-white bg-slate-800' : ''}`}
                >
                  <div className="flex items-center gap-3">
                    {item.icon}
                    {isSidebarOpen && <span className="font-medium text-sm">{item.label}</span>}
                  </div>
                  {isSidebarOpen && (
                    expandedMenu === item.id ? <ChevronDown size={16} /> : <ChevronRight size={16} />
                  )}
                </button>

                {isSidebarOpen && expandedMenu === item.id && (
                  <div className="bg-slate-950 py-1">
                    {item.subItems.map((sub) => (
                      <button
                        key={sub}
                        onClick={() => setActiveTab(sub)}
                        className={`w-full text-left pl-12 pr-4 py-2 text-sm hover:text-white transition-colors
                          ${activeTab === sub ? 'text-indigo-400 font-medium' : 'text-slate-500'}`}
                      >
                        {sub}
                      </button>
                    ))}
                  </div>
                )}
              </>
            ) : (
              <button
                onClick={item.action}
                className={`w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-800 hover:text-white transition-colors
                  ${activeTab === item.id ? 'text-white bg-slate-800 border-l-4 border-indigo-500' : ''}`}
              >
                {item.icon}
                {isSidebarOpen && <span className="font-medium text-sm">{item.label}</span>}
              </button>
            )}
          </div>
        ))}
      </nav>

      <div className="p-4 border-t border-slate-800">
        <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors">
          <LogOut size={20} />
          {isSidebarOpen && <span className="font-medium text-sm">Sign Out</span>}
        </button>
      </div>
    </aside>
  );

  const renderContent = () => {
    switch(activeTab) {
      // Core
      case 'Home': return <Dashboard hourlySales={MOCK_HOURLY_SALES} salesSummary={MOCK_SALES_SUMMARY} />;
      case 'New Sale': return (
        <CashierPOS 
          onLogout={() => setActiveTab('Home')} 
          onProcessSale={handleProcessSale}
          currentUser={currentUser!}
          sharedOrders={orders}
          sharedTransactions={transactions}
          sharedCustomers={customers}
          sharedEmployees={employeesState}
          sharedInventory={inventory}
          sharedCategories={categories}
          sharedDiscounts={discounts}
          sharedTables={MOCK_TABLES}
          sharedReservations={MOCK_RESERVATIONS}
          sharedSchedules={MOCK_SCHEDULES}
          onSeatReservation={(resId, tableId) => console.log('Seat', resId, tableId)}
          integrationConfig={integrationConfig}
          floorPlanTables={floorPlanTables}
          kdsSettings={kdsSettings}
          receiptSettings={receiptSettings}
          onFireToKitchen={handleFireToKitchen} // Pass the KDS firing action
        />
      );

      // Sales Activity
      case 'Orders': return <Orders orders={orders} />;
      case 'Transactions': return <Transactions transactions={transactions} />;
      case 'Cash Log': return <CashLog logs={MOCK_CASH_LOGS} />;
      case 'Invoices': return <Invoices />;
      case 'Recurring Payments': return <RecurringPayments />;

      // Reports
      case 'Sales Report': return <SalesReports salesData={MOCK_SALES_SUMMARY} deposits={MOCK_DEPOSITS} taxReports={MOCK_TAX_REPORTS} initialTab="Daily Sales" />;
      case 'Employee Sales': return <EmployeeSalesReport />;
      case 'Peer Insights': return <PeerInsights totalSales={145000} transactionCount={1200} customers={customers} />;
      case 'Item Sales': return <ItemSales />;
      case 'Removed Items': return <RemovedItems />;
      case 'Tender Types': return <SalesReports salesData={MOCK_SALES_SUMMARY} deposits={MOCK_DEPOSITS} taxReports={MOCK_TAX_REPORTS} initialTab="Tender Types" />;
      case 'Discounts Report': return <SalesReports salesData={MOCK_SALES_SUMMARY} deposits={MOCK_DEPOSITS} taxReports={MOCK_TAX_REPORTS} initialTab="Overview" />;
      case 'Gift Cards Report': return <GiftCardReport />;
      case 'Requested Reports': return <Documents statements={MOCK_STATEMENTS} reports={MOCK_REPORT_REQUESTS} />;

      // Finances
      case 'Overview': return <FinancesOverview />;
      case 'Closeout': return <Closeout />;
      case 'Deposits': return <Deposits />;
      case 'Statements': return <Documents statements={MOCK_STATEMENTS} reports={MOCK_REPORT_REQUESTS} />;
      case 'Taxes': return <SalesReports salesData={MOCK_SALES_SUMMARY} deposits={MOCK_DEPOSITS} taxReports={MOCK_TAX_REPORTS} initialTab="Tax" />;
      case 'Disputes': return <Disputes />;
      case 'Pay Bills': return <PayBills />;

      // Items
      case 'Item Library': return <Items items={inventory} />;
      case 'Categories': return <Categories categories={categories} />;
      case 'Modifier Groups': return <ModifierGroups />;
      case 'Printer Labels': return <PrinterLabels />;
      case 'Discounts': return <Discounts discounts={discounts} setDiscounts={setDiscounts} />;

      // Employees
      case 'Employee List': return (
        <Employees 
            employees={employeesState} 
            onAddEmployee={handleAddEmployee} 
            onUpdateEmployee={handleUpdateEmployee}
            onDeleteEmployee={handleDeleteEmployee}
        />
      );
      case 'Schedule': return <SchedulingApp schedules={MOCK_SCHEDULES} />;
      case 'Time Clock': return <SchedulingApp schedules={MOCK_SCHEDULES} />;

      // Customers
      case 'Customer List': return <Customers customers={customers} />;
      case 'Feedback': return <div className="p-8 text-center text-slate-500">Feedback Dashboard Coming Soon</div>;

      // More / Apps
      case 'Byte Dining': return (
        <DiningDashboard 
          initialTables={floorPlanTables} 
          onSaveFloorPlan={handleSaveFloorPlan} 
        />
      );
      case 'App Market': return <div className="p-8 text-center text-slate-500">App Market Coming Soon</div>;

      default: return <Dashboard hourlySales={MOCK_HOURLY_SALES} salesSummary={MOCK_SALES_SUMMARY} />;
    }
  };

  // --- ROUTING LOGIC ---
  if (currentPath === '/feedback') {
    return <ReceiptFeedback />;
  }

  if (currentPath === '/kitchen') {
    return <KitchenDisplay settings={kdsSettings} />; // KDS is a standalone view when accessed directly
  }

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  if (currentUser.role === UserRole.SUPER_ADMIN) {
    return (
        <div className="bg-slate-100 min-h-screen p-4">
            <div className="max-w-7xl mx-auto space-y-4">
                <div className="flex justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                    <h1 className="font-bold text-slate-800 text-lg">OmniCommand Super Admin</h1>
                    <button onClick={handleLogout} className="text-slate-500 hover:text-red-600 font-medium text-sm">Sign Out</button>
                </div>
                <SuperAdmin 
                    integrationConfig={integrationConfig} 
                    onToggleIntegration={(key) => {
                        setIntegrationConfig(prev => ({...prev, [key]: !prev[key]}));
                        if (key === 'kdsEnabled') {
                            setKdsSettings(prev => ({...prev, isEnabled: !prev.isEnabled}));
                        }
                    }} 
                />
            </div>
        </div>
    );
  }

  if (currentUser.role === UserRole.CASHIER || currentUser.role === UserRole.STAFF) {
    return (
        <CashierPOS 
          onLogout={handleLogout} 
          onProcessSale={handleProcessSale}
          currentUser={currentUser}
          sharedOrders={orders}
          sharedTransactions={transactions}
          sharedCustomers={customers}
          sharedEmployees={employeesState}
          sharedInventory={inventory}
          sharedCategories={categories}
          sharedDiscounts={discounts}
          sharedTables={MOCK_TABLES}
          sharedReservations={MOCK_RESERVATIONS}
          sharedSchedules={MOCK_SCHEDULES}
          onSeatReservation={(resId, tableId) => console.log('Seat', resId, tableId)}
          integrationConfig={integrationConfig}
          floorPlanTables={floorPlanTables}
          kdsSettings={kdsSettings}
          receiptSettings={receiptSettings}
          onFireToKitchen={handleFireToKitchen} // Pass the KDS firing action
        />
    );
  }

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900">
      {renderSidebar()}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shrink-0 z-10">
            <h2 className="font-bold text-lg text-slate-800">{activeTab}</h2>
            <div className="flex items-center gap-4">
                <div className="flex flex-col items-end">
                    <span className="text-sm font-medium text-slate-900">{currentUser.name}</span>
                    <span className="text-xs text-slate-500 uppercase">{currentUser.role.replace('_', ' ')}</span>
                </div>
                <div className="h-10 w-10 bg-indigo-100 rounded-full flex items-center justify-center text-indigo-700 font-bold border border-indigo-200">
                    {currentUser.name.charAt(0)}
                </div>
            </div>
        </header>
        <div className="flex-1 overflow-auto p-6 relative">
            {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;
